  if(!B||typeof B.id!=='number'||typeof NET!=='object'||!NET||!NET.on) return false;
  m={t:'brl',sd:G.seed>>>0,id:B.id,by:(typeof B.by==='number')?(B.by|0):-1};
  if(netEntsHost()){ netBroadcast(m); return true; }
  if(netEntsPeer()){ for(i=0;i<NET.peers.length;i++) if(NET.peers[i].state==='in') netSend(NET.peers[i],m); return true; }
  return false;
}
function brlNetTake(peer,m){
  var B, by, n, i;
  if(!peer||peer.state!=='in') return 'ignored';
  if(typeof m.id!=='number'||m.id!==(m.id|0)||m.id<0) return 'bad';
